391	    if matches!(child.try_wait(), Ok(Some(_))) {
392	        return;
393	    }
394	    #[cfg(unix)]
395	    {
396	        let group = format!("-{}", child.id());
397	        Command::new("kill")
398	            .args(["-TERM", "--", &group])
399	            .stdout(Stdio::null())
400	            .stderr(Stdio::null())
401	            .status()
402	            .ok();
403	    }
404	    #[cfg(windows)]
405	    {
406	        Command::new("taskkill")
407	            .args(["/T", "/F", "/PID", &child.id().to_string()])
408	            .status()
409	            .ok();
410	    }
411	    child.kill().ok();
412	    child.wait().ok();
413	}
