850	        drop(stdin);
851	    }
852	    // Error output reaches the raw stream as it arrives, and is kept for the
853	    // error message should the run end without a result.
854	    let stderr = std::thread::spawn({
855	        let tx = tx.clone();
856	        move || {
857	            let mut text = String::new();
858	            for line in BufReader::new(stderr).lines() {
