870	    // task isn't shown finished while the harness is still at work.
871	    let mut last = None;
872	    for line in BufReader::new(stdout).lines() {
873	        // Stopped, nothing more it prints is taken.
874	        if stop.is_stopped() {
875	            break;
876	        }
877	        let line = line?;
878	        if line.trim().is_empty() {
879	            // Nothing to parse, but the raw stream shows lines as they arrived.
880	            // Once no one is listening, the run is stopped.
881	            if tx.unbounded_send(HarnessEvent::Output(line)).is_err() {
882	                stop.stop();
883	                return Ok(());
884	            }
885	            continue;
886	        }
887	        let events = match serde_json::from_str::<Value>(&line) {
888	            Ok(event) => {
889	                // The skills and agents this run has are offered as mentions.
890	                harness_mentions::remember(&event, project_dir);
891	                let events = parse(&event);
892	                match feed {
893	                    Some(feed) => feed.read(&event, events),
894	                    None => events,
895	                }
896	            }
897	            Err(_) => Vec::new(),
898	        };
