900	            let event = replying.take(event);
901	            if matches!(event, HarnessEvent::Finished { .. }) {
902	                last = Some(event);
903	                continue;
904	            }
905	            if tx.unbounded_send(event).is_err() {
906	                stop.stop();
907	                return Ok(());
908	            }
909	        }
910	    }
911	
912	    let status = stop.wait()?;
913	    // Stopped, it ended as it was asked to; what it left writing to its error
914	    // output is not waited on.
915	    if stop.is_stopped() {
916	        return Ok(());
917	    }
918	    // Its process over, it finishes in the state of its last result.
919	    if let Some(last) = last {
920	        tx.unbounded_send(last).ok();
921	    }
922	    let stderr = stderr.join().unwrap_or_default();
923	    if !replying.finished() {
924	        // A harness that ends without saying it finished, as OpenCode may,
925	        // finished with what it last wrote once it exits cleanly.
926	        if status.success() && agent != Agent::Claude {
927	            tx.unbounded_send(replying.finish()).ok();
928	            return Ok(());
929	        }
930	        let stderr = stderr.trim();
931	        if stderr.is_empty() {
932	            bail!("`{name}` exited with {status}");
933	        }
934	        bail!("{stderr}");
935	    }
936	    Ok(())
937	}
