                markdown,
            ));
        }
        for event in record.events() {
            task.apply(event);
        }
        if record.cancelled {
            task.cancel();
        } else if let Some(error) = record.error {
            task.apply(HarnessEvent::Failed(error));
        }
        task.end();
        task
    }

