#[derive(Clone, Debug, PartialEq)]
enum State {
    Running,
    Succeeded,
    Failed(String),
}

/// What the login's thread reports.
enum Report {
    Output(String),
    Ended(Result<(), String>),
}

pub struct LoginView {
    agent: Agent,
