    /// host's browser, once.
    fn take_output(&mut self, chunk: &str, cx: &mut Context<Self>) {
        for (ix, part) in chunk.split('\n').enumerate() {
            if ix > 0 {
                self.lines.push(String::new());
            }
            if let Some(last) = self.lines.last_mut() {
                last.push_str(part);
