                                    this.update(cx, |this, cx| this.read_containers(project_dir, cx))
                                        .ok();
                                });
                            })),
                    )
                    .into_any_element()
            }
        };
        let logins = v_flex().gap_2().children(Agent::RUNNABLE.into_iter().map(|agent| {
            let state = self
                .containers
                .as_ref()
                .and_then(|containers| {
                    containers
                        .logins
                        .iter()
                        .find(|(known, _)| *known == agent)
                        .map(|(_, logged_in)| *logged_in)
                })
                .flatten();
