            div()
                .text_color(muted)
                .child("Open a project to set its options.")
                .into_any_element()
        };
        v_flex()
            .gap_5()
            .child(podman)
            .child(
                v_flex()
                    .gap_2()
                    .child(div().font_semibold().child("Logins"))
                    .child(logins),
            )
            .child(option)
    }""")
